#!/usr/bin/env python3
"""Off-display HUD & per-agent cursor compositor for ViewPoint Swarm (H3).

Strictly adheres to `swarm/CONTRACT.md` (`claim`, `enqueue`, `turn`, `close`,
`cursor`, `control` records, v=1). Performs zero X11/Wayland connections; all
rendering operates purely in memory on decoded video frames and encodes H.264
(`yuv420p`, `+faststart`) via `/usr/bin/ffmpeg`.
"""

from __future__ import annotations

import argparse
import bisect
import json
import math
import os
import subprocess
import sys
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Dict, List, Optional, Sequence, Tuple

# Enforce headless off-display operation before loading imaging/video backends.
os.environ.pop("DISPLAY", None)
os.environ.pop("WAYLAND_DISPLAY", None)
os.environ.setdefault("QT_QPA_PLATFORM", "offscreen")

import cv2  # noqa: E402
import numpy as np  # noqa: E402
from PIL import Image, ImageDraw, ImageFont  # noqa: E402

