)
RED_VERDICTS = frozenset(
    {
        "CLAIM_REFUSED",
        "NO_LEASE",
        "LEASE_EXPIRED",
        "FRAME_EVICTED",
        "FOOTPRINT_MISSING",
        "JOB_ERROR",
