class FontPack:
    """TrueType font loader with deterministic Linux system font fallbacks."""

    BOLD_CANDIDATES = (
        "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
        "/usr/share/fonts/opentype/urw-base35/NimbusSans-Bold.otf",
        "/usr/share/fonts/truetype/liberation/LiberationSans-Bold.ttf",
    )
    REGULAR_CANDIDATES = (
        "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
        "/usr/share/fonts/opentype/urw-base35/NimbusSans-Regular.otf",
        "/usr/share/fonts/truetype/liberation/LiberationSans-Regular.ttf",
    )
    MONO_CANDIDATES = (
        "/usr/share/fonts/truetype/dejavu/DejaVuSansMono-Bold.ttf",
        "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
    )

    def __init__(self, scale: float = 1.0) -> None:
        s = max(0.5, float(scale))
        self.strip_bold = self._load(self.BOLD_CANDIDATES, max(10, round(14 * s)))
        self.strip_small = self._load(self.BOLD_CANDIDATES, max(9, round(12 * s)))
        self.cursor_bold = self._load(self.BOLD_CANDIDATES, max(9, round(13 * s)))
        self.cursor_sub = self._load(self.REGULAR_CANDIDATES, max(8, round(11 * s)))
        self.caption = self._load(self.REGULAR_CANDIDATES, max(9, round(13 * s)))
        self.mono = self._load(self.MONO_CANDIDATES, max(9, round(12 * s)))

    @staticmethod
    def _load(candidates: Sequence[str], size: int) -> ImageFont.FreeTypeFont | ImageFont.ImageFont:
        for path in candidates:
            if os.path.isfile(path):
                try:
                    return ImageFont.truetype(path, size=size)
                except OSError:
                    continue
        try:
            return ImageFont.load_default(size=size)
        except TypeError:
            return ImageFont.load_default()


def probe_video(input_path: Path) -> VideoMeta:
    """Inspect input MP4 metadata via `ffprobe` with `cv2.VideoCapture` fallback."""
    width = 0
    height = 0
    fps = 15.0
    duration_ms = 0
    nb_frames = 0

    try:
        proc = subprocess.run(
            [
                "ffprobe",
                "-v",
                "error",
                "-select_streams",
                "v:0",
                "-show_entries",
                "stream=width,height,r_frame_rate,avg_frame_rate,nb_frames,duration:format=duration",
                "-of",
                "json",
                str(input_path),
            ],
            check=True,
            capture_output=True,
            text=True,
        )
        info = json.loads(proc.stdout)
        streams = info.get("streams") or []
        if streams:
            st = streams[0]
            width = int(st.get("width") or 0)
            height = int(st.get("height") or 0)
            fps = _parse_rate(st.get("avg_frame_rate")) or _parse_rate(st.get("r_frame_rate")) or 15.0
            if st.get("nb_frames") and str(st["nb_frames"]).isdigit():
                nb_frames = int(st["nb_frames"])
            if st.get("duration"):
                try:
                    duration_ms = int(round(float(st["duration"]) * 1000.0))
                except ValueError:
                    pass
        if duration_ms <= 0 and info.get("format", {}).get("duration"):
            try:
                duration_ms = int(round(float(info["format"]["duration"]) * 1000.0))
            except ValueError:
                pass
    except (subprocess.SubprocessError, json.JSONDecodeError, OSError):
        pass

    if width <= 0 or height <= 0 or duration_ms <= 0:
        cap = cv2.VideoCapture(str(input_path))
        if not cap.isOpened():
            raise RuntimeError(f"Unable to open input video: {input_path}")
        if width <= 0:
            width = int(cap.get(cv2.CAP_PROP_FRAME_WIDTH))
        if height <= 0:
            height = int(cap.get(cv2.CAP_PROP_FRAME_HEIGHT))
        cap_fps = float(cap.get(cv2.CAP_PROP_FPS) or 0.0)
        if cap_fps > 0.1:
            fps = cap_fps
        cap_frames = int(cap.get(cv2.CAP_PROP_FRAME_COUNT) or 0)
        if nb_frames <= 0 and cap_frames > 0:
            nb_frames = cap_frames
        if duration_ms <= 0 and nb_frames > 0 and fps > 0:
            duration_ms = int(round((nb_frames / fps) * 1000.0))
        cap.release()

    if nb_frames <= 0 and duration_ms > 0:
        nb_frames = max(1, int(round((duration_ms / 1000.0) * fps)))
    if duration_ms <= 0:
        duration_ms = max(100, int(round((max(1, nb_frames) / max(1.0, fps)) * 1000.0)))

    return VideoMeta(
        width=width,
        height=height,
        fps=fps,
        duration_ms=duration_ms,
        nb_frames=max(1, nb_frames),
    )


def _parse_rate(rate_str: Optional[str]) -> Optional[float]:
    if not rate_str or not isinstance(rate_str, str):
        return None
    if "/" in rate_str:
        num_s, den_s = rate_str.split("/", 1)
        try:
            num = float(num_s)
            den = float(den_s)
            if den > 0 and num > 0:
                return num / den
        except ValueError:
            return None
    else:
        try:
            val = float(rate_str)
            return val if val > 0 else None
        except ValueError:
            return None
    return None


def load_events(events_path: Path, strict: bool = False) -> List[Dict[str, Any]]:
    """Parse and chronologically order `events.jsonl` per `swarm/CONTRACT.md`."""
    indexed: List[Tuple[int, int, Dict[str, Any]]] = []
    raw_text = events_path.read_text(encoding="utf-8")
    for line_no, raw_line in enumerate(raw_text.splitlines(), start=1):
        line = raw_line.strip()
        if not line:
            continue
        rec = json.loads(line)
        if not isinstance(rec, dict):
            if strict:
                raise ValueError(f"{events_path}:{line_no}: expected JSON object")
            continue
        if strict and rec.get("v") != 1:
            raise ValueError(f"{events_path}:{line_no}: expected v == 1, got {rec.get('v')!r}")
        rec_type = rec.get("rec")
        if rec_type not in VALID_REC_TYPES:
            if strict:
                raise ValueError(f"{events_path}:{line_no}: unknown rec {rec_type!r}")
            continue
        ts_val = rec.get("ts_ms")
        if ts_val is None and rec_type == "claim":
            ts_val = rec.get("issued_ts_ms")
        if ts_val is None:
            if strict:
                raise ValueError(f"{events_path}:{line_no}: missing ts_ms on {rec_type!r}")
            ts_int = 0
        else:
            ts_int = int(ts_val)
        normalized = dict(rec)
        normalized["_ts_ms"] = ts_int
        normalized["_line_no"] = line_no
        indexed.append((ts_int, line_no, normalized))

    indexed.sort(key=lambda item: (item[0], item[1]))
    return [item[2] for item in indexed]


def _discover_sidecar(input_path: Path, explicit_sidecar: Optional[Path]) -> Optional[Dict[str, Any]]:
    candidates: List[Path] = []
    if explicit_sidecar is not None:
        candidates.append(explicit_sidecar)
    else:
        candidates.extend(
            [
                Path(f"{input_path}.meta.json"),
                Path(f"{input_path}.json"),
                input_path.with_suffix(".meta.json"),
                input_path.with_suffix(".json"),
            ]
        )
    for cand in candidates:
        if cand.is_file():
            try:
                data = json.loads(cand.read_text(encoding="utf-8"))
                if isinstance(data, dict):
                    return data
            except (OSError, json.JSONDecodeError):
                continue
    return None


def resolve_timeline(
    input_path: Path,
    video_meta: VideoMeta,
    events: Sequence[Dict[str, Any]],
    start_ts_ms: Optional[int] = None,
    end_ts_ms: Optional[int] = None,
    sidecar_path: Optional[Path] = None,
    timeline_mode: str = "auto",
) -> Tuple[int, int, str]:
    """Determine `[timeline_start_ts_ms, timeline_end_ts_ms, source_mode]`.

    Priority order:
      1. `--start-ts-ms` (explicit CLI flag)
      2. Sidecar JSON (`start_ts_ms` / `started_at_ms`) if overlapping events (or `wallclock` mode)
      3. Input video `mtime - duration` if overlapping events (or `wallclock` mode)
      4. Automatic span `[min(events.ts_ms), max(events.ts_ms)]` when video wall-clock
         timestamps differ from `events.jsonl` (dry-run / time-shifted replay).
    """
    dur = max(1, video_meta.duration_ms)

    if start_ts_ms is not None:
        t0 = int(start_ts_ms)
        t1 = int(end_ts_ms) if end_ts_ms is not None else (t0 + dur)
        return (t0, max(t0 + 1, t1), "explicit")

    action_ts = [int(e["_ts_ms"]) for e in events if e.get("rec") != "claim" and int(e["_ts_ms"]) > 0]
    if not action_ts:
        action_ts = [int(e["_ts_ms"]) for e in events if int(e["_ts_ms"]) > 0]

    sidecar = _discover_sidecar(input_path, sidecar_path)
    sidecar_start: Optional[int] = None
    sidecar_end: Optional[int] = None
    if sidecar is not None:
        for key in ("start_ts_ms", "started_at_ms", "ts_ms"):
            if isinstance(sidecar.get(key), (int, float)):
                sidecar_start = int(sidecar[key])
                break
        if isinstance(sidecar.get("end_ts_ms"), (int, float)):
            sidecar_end = int(sidecar["end_ts_ms"])

    mtime_ms = int(round(os.path.getmtime(input_path) * 1000.0))
    mtime_start = mtime_ms - dur
    mtime_end = mtime_ms

    if not action_ts:
        if sidecar_start is not None:
            t1 = sidecar_end if sidecar_end is not None else (sidecar_start + dur)
            return (sidecar_start, max(sidecar_start + 1, t1), "sidecar_empty")
        return (mtime_start, max(mtime_start + 1, mtime_end), "mtime_empty")

    ev_min = min(action_ts)
    ev_max = max(action_ts)

    if timeline_mode == "span":
        return _build_span_window(ev_min, ev_max, dur)

    if sidecar_start is not None:
